{
  "flashcards": [
    {
      "front": "What is the main goal of database normalization?",
      "back": "To reduce redundancy and avoid update, insert, and delete anomalies in a relational database."
    },
    {
      "front": "What does First Normal Form (1NF) require?",
      "back": "Every attribute must hold atomic, indivisible values, and there must be no repeating groups."
    },
    {
      "front": "When does Second Normal Form (2NF) matter most?",
      "back": "It matters only when the primary key is composite, ensuring no partial dependencies exist."
    },
    {
      "front": "What condition must be met to satisfy Third Normal Form (3NF)?",
      "back": "The table must be in 2NF with no transitive dependencies between non-key attributes."
    },
    {
      "front": "Why might someone deliberately use denormalization?",
      "back": "To speed up read-heavy queries, accepting the cost of extra storage and data redundancy."
    }
  ],
  "warnings": []
}
